fn find_min(a: &[i32], lo: usize) -> usize {
    // Assume `a.len() > 0` and `lo < a.len()`.
    let mut min_idx = lo;
    for i in (lo + 1)..a.len() {
        if a[i] < a[min_idx] {
            min_idx = i;
        }
    }
    min_idx
}

